package br.com.admeclesial.application.catequese;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.domain.catequese.*; import br.com.admeclesial.infrastructure.persistence.catequese.*; import br.com.admeclesial.infrastructure.persistence.organizacao.VinculoFuncaoRepository; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.time.LocalDate; import java.util.*;
@Service public class CatequistaTurmaApplicationService {
 @Autowired private SegurancaOrganizacaoService seguranca;
 private final CatequistaTurmaRepository repository; private final TurmaCatequeseRepository turmaRepository; private final PessoaRepository pessoaRepository; private final VinculoFuncaoRepository vinculoFuncaoRepository;
 public CatequistaTurmaApplicationService(CatequistaTurmaRepository r,TurmaCatequeseRepository t,PessoaRepository p,VinculoFuncaoRepository v){repository=r;turmaRepository=t;pessoaRepository=p;vinculoFuncaoRepository=v;}
 @Transactional public CatequistaTurmaResponse criar(CatequistaTurmaRequest r){validarPeriodo(r.dataInicio(),r.dataFim());var turma=turmaRepository.findByUuid(r.turmaCatequeseUuid()).orElseThrow(()->new CatequeseBusinessException("Turma de catequese não encontrada."));validarAcesso(turma.getOrganizacaoEclesial().getUuid());var pessoa=pessoaRepository.findByUuid(r.pessoaUuid()).orElseThrow(()->new CatequeseBusinessException("Pessoa não encontrada."));if(!pessoa.isAtivo())throw new CatequeseBusinessException("A pessoa está inativa.");if(!vinculoFuncaoRepository.pessoaPossuiFuncaoCatequista(pessoa.getId(),turma.getOrganizacaoEclesial().getId(),r.dataInicio(),r.dataFim()))throw new CatequeseBusinessException("A pessoa não possui função eclesial CATEQUISTA ativa na organização da turma no período informado.");if(repository.existsPessoaConflitante(turma.getId(),pessoa.getId(),r.dataInicio(),r.dataFim(),null))throw new CatequeseBusinessException("A pessoa já está vinculada como catequista nesta turma no período informado.");if(r.principal()&&repository.existsPrincipalConflitante(turma.getId(),r.dataInicio(),r.dataFim(),null))throw new CatequeseBusinessException("Já existe catequista principal na turma para o período informado.");var e=new CatequistaTurma();e.setTurmaCatequese(turma);e.setPessoa(pessoa);e.setDataInicio(r.dataInicio());e.setDataFim(r.dataFim());e.setPrincipal(r.principal());e.setObservacao(text(r.observacao()));return toResponse(repository.save(e));}
 @Transactional(readOnly=true) public List<CatequistaTurmaResponse> listarPorTurma(UUID uuid){var t=turmaRepository.findByUuid(uuid).orElseThrow(()->new CatequeseBusinessException("Turma de catequese não encontrada."));validarAcesso(t.getOrganizacaoEclesial().getUuid());return repository.findAllByTurmaCatequeseIdOrderByPrincipalDescDataInicioAsc(t.getId()).stream().map(this::toResponse).toList();}
 @Transactional(readOnly=true) public List<br.com.admeclesial.application.pessoa.PessoaResponse> listarPessoasElegiveis(UUID turmaUuid, LocalDate dataInicio, LocalDate dataFim){var t=turmaRepository.findByUuid(turmaUuid).orElseThrow(()->new CatequeseBusinessException("Turma de catequese não encontrada."));validarAcesso(t.getOrganizacaoEclesial().getUuid());var inicio=dataInicio!=null?dataInicio:(t.getDataInicio()!=null?t.getDataInicio():LocalDate.now());return vinculoFuncaoRepository.findPessoasElegiveisComoCatequista(t.getOrganizacaoEclesial().getId(),inicio,dataFim).stream().map(p->new br.com.admeclesial.application.pessoa.PessoaResponse(p.getUuid(),p.getNome(),p.getNomeSocial(),p.getDataNascimento(),p.getSexo(),p.getCpf(),p.getRg(),p.getEmail(),p.getObservacao(),p.isAtivo(),p.getDataCadastro())).toList();}
 private CatequistaTurmaResponse toResponse(CatequistaTurma e){return new CatequistaTurmaResponse(e.getUuid(),e.getTurmaCatequese().getUuid(),e.getPessoa().getUuid(),e.getPessoa().getNome(),e.getDataInicio(),e.getDataFim(),e.isPrincipal(),e.getObservacao());}
 private void validarPeriodo(LocalDate i,LocalDate f){if(f!=null&&f.isBefore(i))throw new CatequeseBusinessException("Data final não pode ser anterior à data inicial.");}
 private String text(String v){return StringUtils.hasText(v)?v.trim():null;}

 private void validarAcesso(java.util.UUID uuid){if(seguranca!=null)seguranca.validarAcesso(uuid);}
}
